+void ws_log_set_fatal_count(uint32_t count)
+{
+    fatal_log_count = MIN(1, count);
+}
+
+bool ws_log_set_fatal_count_str(const char *str_count)
+{
+    const char *endptr;
+    uint32_t count;
+    bool result = ws_strtou32(str_count, &endptr, &count);
+
+    if (result && count < 1)
+        result = false;
+
+    if (result)
+        ws_log_set_fatal_count(count);
+
+    return result;
+}

